```python
import json


def _fmt(value):
    return json.dumps(value, sort_keys=True)


def _same(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        if a.keys() != b.keys():
            return False
        return all(_same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(_same(x, y) for x, y in zip(a, b))
    return a == b


def _walk(a, b, path, out):
    if _same(a, b):
        return
    if isinstance(a, dict) and isinstance(b, dict):
        for key in a:
            if key in b:
                _walk(a[key], b[key], path + "." + str(key), out)
            else:
                out.append(f"- {path}.{key}: {_fmt(a[key])}")
        for key in b:
            if key not in a:
                out.append(f"+ {path}.{key}: {_fmt(b[key])}")
        return
    if isinstance(a, list) and isinstance(b, list):
        common = min(len(a), len(b))
        for i in range(common):
            _walk(a[i], b[i], f"{path}[{i}]", out)
        for i in range(common, len(a)):
            out.append(f"- {path}[{i}]: {_fmt(a[i])}")
        for i in range(common, len(b)):
            out.append(f"+ {path}[{i}]: {_fmt(b[i])}")
        return
    out.append(f"~ {path}: {_fmt(a)} -> {_fmt(b)}")


def diff(a, b):
    out = []
    _walk(a, b, "$", out)
    return sorted(out)
```

